const secret = $env.N8N_WEBHOOK_SECRET;
const timestamp = $headers['x-lendloop-timestamp'];
const eventId = $headers['x-lendloop-event-id'];
const signature = String($headers['x-lendloop-signature'] || '').replace(/^sha256=/, '');
const crypto = require('crypto');
const item = $input.first();
const rawBody = item.binary?.data?.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json);
if (!timestamp || !eventId || !secret) throw new Error('Missing signed webhook fields');
if (!/^\d+$/.test(timestamp) || Math.abs(Date.now() - Number(timestamp)) > 300000) throw new Error('Replay-protected timestamp rejected');
const expected = crypto.createHmac('sha256', secret).update(timestamp + '.' + rawBody).digest('hex');
if (!/^([a-f0-9]{64})$/i.test(signature)) throw new Error('Invalid HMAC signature format');
if (!crypto.timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(expected, 'hex'))) throw new Error('Invalid HMAC signature');
const staticData = $getWorkflowStaticData('global');
staticData.seenEvents ||= {};
const now = Date.now();
for (const key of Object.keys(staticData.seenEvents)) {
  if (now - staticData.seenEvents[key] > 600000) delete staticData.seenEvents[key];
}
if (staticData.seenEvents[eventId]) throw new Error('Duplicate event rejected');
staticData.seenEvents[eventId] = now;
return [{ json: item.json }];

const event = $json;
console.log(`[LendLoop notification] ${event.type} for loan ${event.loanId}`);
return [{ json: { eventId: event.eventId, delivered: true, recipientId: event.recipientId } }];

const error = $json.error?.message || 'Unknown borrow notification workflow error';
console.error(`[LendLoop borrow notification failure] ${error}`);
return [{ json: { recorded: false, error } }];
